package com.fooddelivery.restaurant;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;import java.util.*;import com.fooddelivery.restaurant.entity.*;import com.fooddelivery.restaurant.repository.RestaurantRepository;@Configuration public class DataInitializer{@Bean CommandLineRunner seed(RestaurantRepository r){return args->{if(r.count()==0){Restaurant x=new Restaurant();x.setName("Andhra Spice Kitchen");x.setAddress("Downtown");x.setCuisine("Indian");MenuItem a=new MenuItem();a.setId("biryani");a.setName("Chicken Biryani");a.setDescription("Hyderabadi-style biryani");a.setPrice(14.99);MenuItem b=new MenuItem();b.setId("dosa");b.setName("Masala Dosa");b.setDescription("Crispy dosa with potato masala");b.setPrice(9.99);x.setMenu(Arrays.asList(a,b));r.save(x);}};}}
